import numpy as np
from itertools import permutations

def feature(current, candidates, tour, start):
    """Negative exact optimal tail cost (current -> perm -> start) for the first city of the best permutation, gated to k <= 4, normalised."""
    k = len(candidates)
    if k > 4:
        return np.zeros(k)
    d_cur = np.linalg.norm(candidates - current, axis=1)
    d_start = np.linalg.norm(candidates - start, axis=1)
    best = np.full(k, np.inf)
    for perm in permutations(range(k)):
        cost = d_cur[perm[0]]
        for i in range(k - 1):
            cost += np.linalg.norm(candidates[perm[i]] - candidates[perm[i + 1]])
        cost += d_start[perm[-1]]
        if cost < best[perm[0]]:
            best[perm[0]] = cost
    v = -best
    return v / (np.max(np.abs(v)) + 1e-9)
```

This computes, for each candidate, the negative of the exact shortest tail cost (current → that candidate → remaining candidates in any order → start), enumerating all permutations when k ≤ 4 and returning zeros otherwise, then normalises by the max absolute value; I read "best[perm[0]] = min over permutations" as the minimum total tail cost among permutations starting with that candidate.

