    """Negative of (distance from current to candidate plus candidate's nearest-other-candidate distance), standardised."""
    k = len(candidates)
    if k < 2:
        return np.zeros(k)
    d_cur = np.linalg.norm(candidates - current, axis=1)
    diff = candidates[:, None, :] - candidates[None, :, :]
    D = np.sqrt((diff ** 2).sum(axis=2))
    np.fill_diagonal(D, np.inf)
    nn_next = D.min(axis=1)
    v = -(d_cur + nn_next)
