def _f100(current, candidates, tour, start):
    """For each candidate: the 1-nearest-neighbour distance from that candidate to the nearest other unvisited city, minus its distance to the current city, normalised: prefers candidates that are not isolated in the remaining set (avoids stranding outliers)."""
